@php $progress = $staffDailyTarget > 0 ? min(100, ($staffAchieved / $staffDailyTarget) * 100) : 0; @endphp
<div class="report-section-grid"><div class="report-column"><article class="report-block"><h2>Staff Daily Target</h2><div class="report-stat-grid"><div class="report-stat"><span>Total Daily Target</span><strong>₹{{ number_format($staffDailyTarget, 2) }}</strong></div><div class="report-stat"><span>Total Achieved</span><strong>₹{{ number_format($staffAchieved, 2) }}</strong></div><div class="report-stat"><span>Remaining</span><strong>₹{{ number_format(max(0, $staffDailyTarget - $staffAchieved), 2) }}</strong></div><div class="report-stat"><span>Progress</span><strong>{{ number_format($progress, 1) }}%</strong></div></div><div style="margin-top:18px" class="progress-track"><i style="width:{{ $progress }}%"></i></div></article><article class="report-block"><h2>Staff Performance</h2>@if($staffPerformance->isNotEmpty())<table class="report-table"><thead><tr><th>Staff</th><th>Achieved</th><th>Progress</th></tr></thead><tbody>@foreach($staffPerformance as $staff)<tr><td>{{ $staff['name'] }}</td><td>₹{{ number_format($staff['achieved'], 2) }}</td><td>{{ $staffDailyTarget > 0 ? number_format(($staff['achieved'] / $staffDailyTarget) * 100, 1) : 0 }}%</td></tr>@endforeach</tbody></table>@else<div class="report-empty">No completed staff work available for this date range.</div>@endif</article></div></div>
